import json
OURS = {"111122223333", "444455556666"}          # our AWS account IDs
TAMPER = {"StopLogging", "DeleteTrail", "UpdateTrail", "PutEventSelectors"}

def rules(e):
    """Return (ATT&CK id, reason) for each rule a simplified event trips."""
    hits, p = [], e.get("params", {})
    me = e["arn"].split("/")[-1]
    if e["name"] == "CreateAccessKey" and p.get("userName", me) != me:
        hits.append(("T1098.001", f"{me} made a key for {p['userName']}"))
    if e["name"] in TAMPER:
        hits.append(("T1685.002", f"{e['name']} on {p['name']}"))
    if e["name"] == "UpdateAssumeRolePolicy":
        new = set(json.loads(p["policyDocument"])["trustAccounts"]) - OURS
        if new:
            hits.append(("T1098", f"role now trusts {sorted(new)}"))
    if e["name"] == "ModifySnapshotAttribute" and p["addAccount"] not in OURS:
        hits.append(("T1537", f"snapshot shared with {p['addAccount']}"))
    return hits

