# Blast radius of one identity: follow "can reach" edges (synthetic graph).
from collections import deque

CAN_REACH = {
    "contractor (IdP)":    ["VPN", "wiki", "file share"],
    "file share":          ["script with PAM admin password"],
    "script with PAM admin password": ["PAM vault (admin)"],
    "PAM vault (admin)":   ["AWS console", "GCP console", "Slack admin", "build secrets"],
    "AWS console":         ["S3 buckets", "IAM"],
}

def blast_radius(start):
    seen, order, queue = {start}, [], deque([(start, 0)])
    while queue:
        node, hops = queue.popleft()
        order.append((hops, node))
        for nxt in CAN_REACH.get(node, []):
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, hops + 1))
    return order

for hops, node in blast_radius("contractor (IdP)"):
